          "severity": "",
          "sources": [
            {
              "count": 10,
              "items": [
                {
                  "id": "01a2024a-d55f-7794-b110-3faccd8127be",
                  "status": "",
                  "title": "One model, one store, one action registry"
                },
                {
                  "id": "01a2024a-d5a8-7e76-8653-a51a41a7d706",
                  "status": "",
                  "title": "Every mutation is an action; the database is not the API"
                },
                {
                  "id": "01a2024a-d5f0-7ea4-a34b-12b0720a4380",
                  "status": "",
                  "title": "Tenant isolation is structural, not a filter"
                },
                {
                  "id": "01a2024a-d63a-7fdd-8331-90f1d8ec4df0",
                  "status": "",
                  "title": "Publication is a decision, never a side effect"
                },
                {
                  "id": "01a2024a-d685-7305-8c59-c8a803359ecf",
                  "status": "",
                  "title": "Every output is versioned, attributable and reversible"
                },
                {
                  "id": "01a2024a-d6cc-7fd9-873d-36d0e1e8a0b0",
                  "status": "",
                  "title": "Programme truth is computed, never hand-written"
                },
                {
                  "id": "01a2024a-d716-7db7-98a8-4adaeba82a52",
                  "status": "",
                  "title": "Gates refuse; a gate that never refuses is broken"
                },
                {
                  "id": "01a2024a-d760-7de8-b735-3035ebcb2807",
                  "status": "",
                  "title": "Typed dependencies, explicit gates"
                },
                {
                  "id": "01a2024a-d7b1-70de-b58c-9b73d05e2baf",
                  "status": "",
                  "title": "Secrets never leave their boundary"
                },
                {
                  "id": "01a2024a-d7fb-7735-a7e4-d07243f60745",
                  "status": "",
                  "title": "The estate is one deployable service per concept, absorbed not duplicated"
                }
              ],
              "kind": "computed",
              "name": "artifact_entries"
            }
          ],
          "status": "evidenced"
